use vstd::prelude::*;
use vstd::string::*;

verus! {

// Define Set A characters
spec fn is_set_a(c: char) -> bool {
    c == 'A' || c == 'E' || c == 'F' || c == 'H' || c == 'I' || 
    c == 'K' || c == 'L' || c == 'M' || c == 'N' || c == 'T' ||
    c == 'V' || c == 'W' || c == 'X' || c == 'Y' || c == 'Z'
}

// Define Set B characters
spec fn is_set_b(c: char) -> bool {
    c == 'B' || c == 'C' || c == 'D' || c == 'G' || c == 'J' ||
    c == 'O' || c == 'P' || c == 'Q' || c == 'R' || c == 'S' || c == 'U'
}

// Specification: all characters in a vector belong to the same set
spec fn all_same_set(word: Seq<char>) -> bool {
    if word.len() == 0 {
        true
    } else {
        let first_in_a = is_set_a(word[0]);
        forall|i: int| 0 <= i < word.len() ==> 
            (first_in_a && is_set_a(word[i])) || (!first_in_a && is_set_b(word[i]))
    }
}

fn solve(word: Vec<char>) -> (result: Vec<char>)
    requires
        word@.len() >= 1 && word@.len() <= 10,
        forall|i: int| 0 <= i < word@.len() ==> 
            'A' as u32 <= word@[i] as u32 <= 'Z' as u32,
    ensures
        result@ == new_strlit("YES")@ || result@ == new_strlit("NO")@,
        result@ == new_strlit("YES")@ <==> all_same_set(word@),
{
    let mut i: usize = 0;
    let mut found_a: bool = false;
    let mut found_b: bool = false;
    let mut all_same: bool = true;
    
    while i < word.len()
        invariant
            0 <= i <= word@.len(),
            i < word@.len() ==> (found_a == exists|j: int| 0 <= j < i && is_set_a(word@[j])),
            i < word@.len() ==> (found_b == exists|j: int| 0 <= j < i && is_set_b(word@[j])),
            all_same == (forall|j: int, k: int| 0 <= j < i && 0 <= k < i ==> 
                (is_set_a(word@[j]) && is_set_a(word@[k])) || 
                (is_set_b(word@[j]) && is_set_b(word@[k]))),
            word@.len() >= 1 && word@.len() <= 10,
            forall|idx: int| 0 <= idx < word@.len() ==> 
                'A' as u32 <= word@[idx] as u32 <= 'Z' as u32,
        decreases word.len() - i,
    {
        let c = word[i];
        
        // Character must be in either Set A or Set B (since all are A-Z)
        assert(is_set_a(c) || is_set_b(c));
        
        if is_set_a(c) {
            found_a = true;
            if found_b {
                all_same = false;
            }
        } else { // is_set_b(c) must be true
            found_b = true;
            if found_a {
                all_same = false;
            }
        }
        
        i = i + 1;
    }
    
    // Prepare result
    if all_same {
        let yes_str = Vec::from_str("YES");
        yes_str
    } else {
        let no_str = Vec::from_str("NO");
        no_str
    }
}

} // verus!

